import pathlib,subprocess,json,urllib.parse,hashlib
out=pathlib.Path('/tmp/mangrove-drawer-source-20261006');out.mkdir(exist_ok=True);session='mangrove-drawer-source'
def cli(*args):
 r=subprocess.run(['agent-browser','--session',session,'--json',*args],capture_output=True,text=True,check=True);j=json.loads(r.stdout)
 if not j['success']:raise RuntimeError(j)
 return j['data'].get('result',j['data'])
props='display visibility position transform opacity backgroundColor backgroundImage backgroundOrigin backgroundPosition backgroundSize color fontFamily fontSize fontWeight fontStyle lineHeight letterSpacing textAlign textDecorationLine textDecorationThickness textUnderlineOffset textWrapStyle whiteSpace overflowX overflowY boxSizing boxShadow outlineColor outlineStyle outlineWidth outlineOffset borderTopColor borderRightColor borderBottomColor borderLeftColor borderTopWidth borderRightWidth borderBottomWidth borderLeftWidth borderTopStyle borderRightStyle borderBottomStyle borderLeftStyle borderTopLeftRadius borderTopRightRadius borderBottomLeftRadius borderBottomRightRadius paddingTop paddingRight paddingBottom paddingLeft marginTop marginRight marginBottom marginLeft gap alignItems justifyContent flexDirection maskImage maskSize maskPosition content width height'.split()
js='''(async()=>{await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const props=PROPS,root=document.querySelector('.mg-drawer,.mg-floating-panel');const read=(n,p)=>{const s=getComputedStyle(n,p);return Object.fromEntries(props.map(k=>[k,s[k]]));};const rect=n=>{let r=n.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height};};const nodes=[];function walk(n,id,parentId){const texts=[];for(const [i,t] of [...n.childNodes].entries()){if(t.nodeType!==3||!t.textContent.trim())continue;const range=document.createRange();range.selectNodeContents(t);texts.push({id:i,characters:t.textContent,rects:[...range.getClientRects()].map(r=>({x:r.x,y:r.y,width:r.width,height:r.height}))});}nodes.push({id,parentId,tag:n.tagName,classes:n.className,rect:rect(n),style:read(n),before:read(n,'::before'),after:read(n,'::after'),texts,href:n.getAttribute('href'),ariaLabel:n.getAttribute('aria-label'),role:n.getAttribute('role'),checked:n.tagName==='INPUT'?n.checked:undefined,focused:n===document.activeElement,focusVisible:n.matches(':focus-visible'),scrollTop:n.scrollTop,scrollHeight:n.scrollHeight,clientHeight:n.clientHeight});[...n.children].forEach((c,i)=>walk(c,id+'-'+i,id));}walk(root,'root',null);const backdrop=document.querySelector('.mg-drawer__backdrop');return {url:location.href,fontStatus:document.fonts.status,fonts:[...document.fonts].map(f=>({family:f.family,weight:f.weight,style:f.style,status:f.status})),fontRequests:performance.getEntriesByType('resource').filter(e=>/woff|ttf/.test(e.name)).map(e=>e.name),viewport:{width:innerWidth,height:innerHeight},nodes,backdrop:backdrop?{rect:rect(backdrop),style:read(backdrop)}:null,bodyStyle:read(document.body),aliases:Object.fromEntries(['--mg-control-border','--mg-control-background','--mg-control-text'].map(k=>[k,getComputedStyle(document.body).getPropertyValue(k)])),activeElement:document.activeElement.className};})()'''.replace('PROPS',json.dumps(props))
def save(mode,story,width,state):
 c=cli('eval',js);c['contract']={'mode':mode,'story':story,'width':width,'state':state};path=out/f'{mode}-{story}-{width}-{state}.json';path.write_text(json.dumps(c,indent=2)+'\n');print(path.name,flush=True)
def settle(opened=True):cli('wait','--fn',"(()=>{const n=document.querySelector('.mg-drawer,.mg-floating-panel'),s=getComputedStyle(n);return n&&"+("n.classList.contains('is-open')&&s.visibility==='visible'&&s.display!=='none'&&s.transform==='none'" if opened else "!n.classList.contains('is-open')&&(s.visibility==='hidden'||s.display==='none')")+"})()")
themes={'undrr':'Global UNDRR Theme','delta':'DELTA Resilience Theme','irp':'IRP Theme','mcr':'MCR2030 Theme','preventionweb':'PreventionWeb Theme'}
try:
 for mode,theme in themes.items():
  for width in [390,1164]:
   cli('set','viewport',str(width),'1000')
   for story in ['default','end','bottom','floating-panel','vanilla-lifecycle']:
    url='http://localhost:6121/iframe.html?'+urllib.parse.urlencode({'id':'components-navigation-drawer--'+story,'viewMode':'story','globals':'theme:'+theme+';locale:english'});cli('open',url);cli('wait','--fn',"Boolean(document.querySelector('.mg-drawer,.mg-floating-panel'))");settle(False);save(mode,story,width,'closed')
    cli('click','#storybook-root > button' if story!='vanilla-lifecycle' else '[data-mg-drawer-trigger]');settle();save(mode,story,width,'open')
    if story=='default':
     cli('hover','.mg-drawer__close');save(mode,story,width,'close-hover');cli('hover','.mg-drawer__body');cli('press','Tab');cli('press','Shift+Tab');save(mode,story,width,'close-focus');cli('check','.mg-form-check:first-of-type input[name=hazard]');save(mode,story,width,'checked')
    if story=='floating-panel':cli('check','.mg-form-check:nth-of-type(2) input[name=layer]');save(mode,story,width,'checked')
    if story=='bottom':cli('eval',"document.querySelector('.mg-drawer__body').scrollTop=document.querySelector('.mg-drawer__body').scrollHeight");save(mode,story,width,'scroll-end')
    cli('click','.mg-drawer__close,.mg-floating-panel__close');settle(False);save(mode,story,width,'closed-restored')
finally:cli('close')
